CREATE OR ALTER PROCEDURE [dbo].[uspDish_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @DishCategoryId UNIQUEIDENTIFIER = NULL
	, @DefaultUnitId UNIQUEIDENTIFIER = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @Description NVARCHAR(MAX) = NULL
	, @StandardServingSize DECIMAL(18,4) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[Code]
			, t.[Name]
			, t.[MealCategory]
			, t.[Description]
			, t.[StandardPortion]
			, t.[StandardCost]
			, t.[Status]
			, t.[DishCategoryId]
			, j1.[Name] AS [DishCategoryName]
			, t.[DefaultUnitId]
			, j2.[Name] AS [DefaultUnitName]
			, t.[StandardServingSize]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[Dishe] AS t
		LEFT JOIN [dbo].[DishCategorie] AS j1 ON j1.[Id] = t.[DishCategoryId]
		LEFT JOIN [dbo].[UnitMeasure] AS j2 ON j2.[Id] = t.[DefaultUnitId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@DishCategoryId IS NULL OR t.[DishCategoryId] = @DishCategoryId)
			AND (@DefaultUnitId IS NULL OR t.[DefaultUnitId] = @DefaultUnitId)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (ISNULL(@Description, '') = '' OR t.[Description] LIKE CONCAT('%', @Description, '%'))
			AND (@StandardServingSize IS NULL OR t.[StandardServingSize] = @StandardServingSize)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealCategory' THEN r.[MealCategory] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealCategory' THEN r.[MealCategory] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardPortion' THEN r.[StandardPortion] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardPortion' THEN r.[StandardPortion] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardCost' THEN r.[StandardCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardCost' THEN r.[StandardCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishCategoryId' THEN r.[DishCategoryId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishCategoryId' THEN r.[DishCategoryId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishCategoryName' THEN r.[DishCategoryName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishCategoryName' THEN r.[DishCategoryName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'defaultUnitId' THEN r.[DefaultUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'defaultUnitId' THEN r.[DefaultUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'defaultUnitName' THEN r.[DefaultUnitName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'defaultUnitName' THEN r.[DefaultUnitName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardServingSize' THEN r.[StandardServingSize] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardServingSize' THEN r.[StandardServingSize] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
